  g = { {"rechterstuk", "right piece"}, {"hierna", "next, after this"}, {"dodenbezwering", "necromancy"}, {"spookachtige", "spectral, ghostly (spookachtig)"}, {"herenigde", "recombined, reunited (herenigen)"}, {"prijs", "commend, praise (prijzen)"}, {"verzeker", "assure (verzekeren)"}, {"tenminste", "at least"}, {"vuurschaal", "brazier"}, {"af te stemmen", "to attune (afstemmen)"} },
},

